function drawEnvironment(t){for(const d of debris){ctx.globalAlpha=Math.min(.5,d.life/5);ctx.fillStyle=d.kind==='wood'?'#a98256':'#413e4a';for(let i=0;i<5;i++)ctx.fillRect(d.x+Math.sin(i*7)*20,d.y+Math.cos(i*4)*15,9,4);ctx.globalAlpha=1}for(const h of hazards){const c=h.kind==='poison'?'#a4ed71':'#ffad67',active=h.arm<=0;ctx.globalAlpha=Math.min(1,h.life/.6);ctx.fillStyle=h.kind==='poison'?'#70ae452b':'#ed763429';ctx.beginPath();ctx.ellipse(h.x,h.y,h.r,h.r,0,0,Math.PI*2);ctx.fill();ctx.setLineDash(active?[]:[6,6]);ctx.strokeStyle=c;ctx.lineWidth=1.5;ctx.stroke();ctx.setLineDash([]);for(let i=0;i<15;i++){const a=i*2.4,rr=(.25+(i%4)*.18)*h.r,x=h.x+Math.cos(a)*rr,y=h.y+Math.sin(a)*rr;if(h.kind==='fire'){const height=9+9*(.5+.5*Math.sin(t*9+i));ctx.fillStyle='#ff8b47aa';ctx.fillRect(x-4,y-height,8,height);ctx.fillStyle='#ffe393bb';ctx.fillRect(x-2,y-height*.6,4,height*.6)}else{ctx.fillStyle='#a8eb6c30';ctx.beginPath();ctx.arc(x+Math.sin(t+i)*4,y-6,9+Math.sin(t*2+i)*3,0,Math.PI*2);ctx.fill()}}ctx.globalAlpha=1;ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillStyle=c;ctx.fillText(h.kind==='poison'?'毒气 / 可引燃':'燃烧区域',h.x,h.y+h.r+13)}for(const a of arrivals){const progress=1-a.t/a.max,r=a.r+21;ctx.save();ctx.translate(a.x,a.y);ctx.scale(1,.6);ctx.fillStyle='#ad65ff22';ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();circle(0,0,r,'#cc9cff',2);ctx.rotate(t*2);ctx.strokeStyle='#f4d6ff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,r+6,0,Math.PI*2*progress);ctx.stroke();for(let i=0;i<4;i++){ctx.rotate(Math.PI/2);ctx.fillStyle='#e6bdff';ctx.fillRect(r-3,-3,7,6)}ctx.restore();ctx.fillStyle=`rgba(191,133,255,${progress*.22})`;ctx.fillRect(a.x-r*.5,a.y-70*progress,r,70*progress);ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillStyle='#e1bcff';ctx.fillText(a.type==='boss'?'核心降临':'裂隙凝聚',a.x,a.y+30);}}
function drawProp(o,t){const p=propCenter(o),d=propKinds[o.kind];shadow(p.x,p.y+17,24);ctx.save();ctx.translate(p.x+(o.flash>0?Math.sin(t*70)*2:0),p.y);ctx.fillStyle=o.flash>0?'#f5e0be':'#20212c';ctx.fillRect(-21,-24,42,44);ctx.fillStyle=d.color;ctx.globalAlpha=.82;ctx.fillRect(-18,-22,36,35);ctx.globalAlpha=1;ctx.fillStyle='#17202c';ctx.fillRect(-16,-16,32,3);ctx.fillRect(-16,7,32,4);if(o.kind==='wood'){ctx.strokeStyle='#674528';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-14,-17);ctx.lineTo(14,9);ctx.moveTo(14,-17);ctx.lineTo(-14,9);ctx.stroke();ctx.fillStyle='#e4c08b';ctx.fillRect(-17,-18,5,5);ctx.fillRect(12,9,5,5);if(o.variant%2){ctx.fillStyle='#dad1af';ctx.fillRect(-7,-10,14,8);ctx.fillStyle='#785c44';ctx.fillRect(-4,-8,8,2)}else{ctx.fillStyle='#705440';ctx.fillRect(-16,-2,32,3)}}else{ctx.fillStyle='#26323c';ctx.fillRect(-12,-12,24,19);ctx.fillStyle=o.fuse>=0&&Math.sin(t*35)>0?'#fff':d.color;ctx.font='bold 18px monospace';ctx.textAlign='center';ctx.fillText(d.glyph,0,4);ctx.fillStyle='#b8bcc3';ctx.fillRect(-13,-26,26,4)}if(o.hp<o.maxHp&&o.fuse<0){ctx.fillStyle='#15232a';ctx.fillRect(-18,-32,36,3);ctx.fillStyle=d.color;ctx.fillRect(-18,-32,36*Math.max(0,o.hp)/o.maxHp,3)}ctx.restore();if(o.fuse>=0){circle(p.x,p.y,o.kind==='blast'?112:o.kind==='poison'?82:72,'#ffb79799',2);ctx.fillStyle='#ffd6b4';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillRect(p.x-3,p.y-40,6,9)}}

