function offerAvailable(o){const left=(shopStock[o.id]||0)<o.stock;return left&&(!o.valid||o.valid())&&(o.currency==='coin'?coins>=o.cost:player.maxHp-o.cost>=3);}
function buyOffer(index){if(mode!=='shop')return false;const o=shopOffers[shopId]?.[index];if(!o||!offerAvailable(o))return false;if(o.currency==='coin')coins-=o.cost;else{player.maxHp-=o.cost;player.hp=Math.min(player.hp,player.maxHp)}shopStock[o.id]=(shopStock[o.id]||0)+1;o.apply();if(!['potion','battery','mint'].includes(o.id))purchasedSkills.add(o.id);sound.tone(420,.16,'triangle',.06,840);paintShop();updateHUD();return true;}
