function impendingHit(){const window=.2;for(const b of enemyBullets){if(b.life<=0||dist(b,player)>150)continue;const vx=b.vx,vy=b.vy,s2=vx*vx+vy*vy;if(s2<1)continue;const dx=player.x-b.x,dy=player.y-b.y,t=(dx*vx+dy*vy)/s2;if(t>=0&&t<=window&&Math.hypot(dx-vx*t,dy-vy*t)<player.r+b.r+5)return true;}for(const l of bossLanes){if(l.fired||l.wind<0||l.wind>.2)continue;const dx=player.x-l.x,dy=player.y-l.y,along=dx*Math.cos(l.a)+dy*Math.sin(l.a),perp=Math.abs(dx*Math.sin(l.a)-dy*Math.cos(l.a));if(along>0&&along<l.length&&perp<player.r+6){let occluded=false;for(let d=20;d<along;d+=16)if(blocked(l.x+Math.cos(l.a)*d,l.y+Math.sin(l.a)*d,2)){occluded=true;break}if(!occluded)return true;}}return false;}
function counterVolleyV10(){const targets=enemies.filter(e=>!e.dead&&e.state!=='spawn'&&!e.airborne&&dist(e,player)<850).sort((a,b)=>dist(a,player)-dist(b,player));if(!targets.length)return;const n=3+(player.counterExtra||0);for(let i=0;i<n;i++){const e=targets[i%targets.length],a=angle(player,e)+(i-(n-1)/2)*.035;bullets.push({x:player.x+Math.cos(a)*28,y:player.y-5+Math.sin(a)*28,vx:Math.cos(a)*650,vy:Math.sin(a)*650,r:5,damage:14,life:1.3,pierce:0,hit:new Set(),red:phase,canBounce:false,bounces:0,counter:true})}}
function switchPhaseV10(){if(mode!=='play'||player.shiftCd>0){switchPhaseTactical();return}const perfect=!inLobby&&player.perfectCd<=0&&impendingHit();switchPhaseTactical();if(player.shiftPower)player.phasePowerTime=1.2;if(perfect){perfectCount++;player.perfectCd=5;player.inv=Math.max(player.inv,.42);player.resonance=Math.min(100,(player.resonance||0)+26);perfectFlash=.8;counterVolley();floater(player.x,player.y-65,'精准换界！','#ffe3a1');toast('精准换界 · 反击弹 + 共鸣26 · 5秒后可再次精准判定',2.7);sound.tone(850,.15,'square',.045,1300)}updateHUD();}
