function updateHUDV10(){updateHUDJourney();if(!player)return;const z=currentService();if(z){$('#roomName').textContent=z.name;$('#objective').textContent='安全小房间 · 靠近柜台按E交易';$('#waveLabel').textContent='SIDE ROOM / '+(z.id==='clinic'?'SUPPLY':'CONTRACT')}if(['play','pause','upgrade'].includes(mode)){const cd=player.perfectCd||0;$('#resonancePanel small').textContent=cd>0?'精准换界 '+cd.toFixed(1)+'s / 危急时Tab仍可清弹':'敌弹即将命中时Tab → 精准反击 +26共鸣';}$('#phaseCooldown').textContent=player.shiftCd>0?player.shiftCd.toFixed(1)+'s / 换界冷却':player.resonance>=100?'TAB / 共鸣爆发':'TAB / 换界清弹 · 临危精准反击';}
