function drawServiceRooms(t){for(const z of serviceRooms){if(z.x>camera.x+W||z.x+z.w<camera.x||z.y>camera.y+H||z.y+z.h<camera.y)continue;const p=servicePoint(z),medical=z.id==='clinic';ctx.fillStyle='#101c27';ctx.fillRect(p.x-118,p.y-78,236,68);ctx.fillStyle=medical?'#799b8c':'#9f708e';ctx.fillRect(p.x-122,p.y-82,244,12);ctx.fillStyle=medical?'#254938':'#4c263b';ctx.fillRect(p.x-110,p.y-65,220,43);ctx.fillStyle=medical?'#99e9b0':'#f396b5';ctx.font='bold 18px monospace';ctx.textAlign='center';ctx.fillText(z.name,p.x,p.y-38);for(let i=0;i<3;i++){const x=p.x-74+i*74;ctx.fillStyle='#121c29';ctx.fillRect(x-24,p.y+4,48,28);if(medical){ctx.fillStyle=['#e5899e','#96d9f1','#e4d399'][i];ctx.fillRect(x-8,p.y-22,16,26);ctx.fillStyle='#d5e9df';ctx.fillRect(x-5,p.y-29,10,7);ctx.fillRect(x-6,p.y-12,12,3)}else{ctx.fillStyle='#b96183';ctx.fillRect(x-13,p.y-17,26,21);ctx.fillStyle='#e5adba';ctx.fillRect(x-10,p.y-22,20,4);ctx.fillStyle='#f1d59e';ctx.fillRect(x-2,p.y-10,4,13)}}drawSprite('robot',p.x-148,p.y+30,52,{squash:1+Math.sin(t*3)*.02});ctx.font='13px monospace';ctx.fillStyle='#c6d6cb';ctx.fillText(medical?'金币 · 药剂 · 技能':'生命上限 · 血契道具',p.x,p.y+78);ctx.font='12px monospace';ctx.fillStyle='#b2c9bd';ctx.fillText('E 查看交易',p.x,p.y+103);}}
function routeMapMarkup(){const all=[...zones,...serviceRooms],xy=([x,y])=>[10+(x-100)*.032,14+(y-100)*.047],nodes=all.map(z=>xy([z.x+z.w/2,z.y+z.h/2])),service=currentService();return `<svg viewBox="0 0 270 155" role="img" aria-label="主线与工坊回路，前庭南侧补给室，转运港东侧血契室">${routeEdges.map(e=>`<polyline points="${[nodes[e.a],...e.p.map(xy),nodes[e.b]].map(p=>p.join(',')).join(' ')}" fill="none" stroke="${e.service?'#ac7391':e.optional?'#aa975b':'#4c6c7c'}" stroke-width="2" ${(e.optional||e.service)?'stroke-dasharray="4 3"':''}/>`).join('')}${nodes.map(([x,y],i)=>{const active=i<6?!service&&i===roomIndex:service?.id===all[i].id,done=i<6?clearedRooms.has(i):visitedServices.has(all[i].id);return `<g><rect x="${x-10}" y="${y-8}" width="20" height="16" fill="${active?'#386878':done?'#255346':'#112535'}" stroke="${active?'#d6ffff':i>=6?'#e59ab8':i===2?'#e3bf70':done?'#81cdb1':'#5a7483'}" stroke-width="2"/><text x="${x}" y="${y+4}" fill="#dae7de" text-anchor="middle" font-size="11">${i>=6?all[i].map:i===2?'◇':i===5?'核':i+1}</text></g>`}).join('')}</svg><small>◇ 工坊 / + 补给 / 契 血契</small>`;}
function renderV10(t){if(mode==='bossintro'){drawBossArrival(t);return}renderJourney(t);if(!inLobby&&!['title','guide','epilogue'].includes(mode)){ctx.save();ctx.translate(-camera.x,-camera.y);drawServiceRooms(t);if(gatePulse>0){for(const edge of routeEdges)if(routeIsLocked(edge)){const g=gateFor(edge,roomIndex);ctx.strokeStyle='#ff9dbb';ctx.lineWidth=3;ctx.strokeRect(g.x-4,g.y-4,g.w+8,g.h+8)}}ctx.restore();}if(perfectFlash>0&&mode==='play'){ctx.fillStyle='#ffe5a10a';ctx.fillRect(0,0,W,H);ctx.fillStyle='#ffe4a3';ctx.font='bold 23px monospace';ctx.textAlign='center';ctx.fillText('ECHO SHIFT / 回响换界',W/2,140);}if(mode==='bossdeath'&&fallenBoss)drawBossDefeat(t);}
function drawBossArrival(t){ctx.fillStyle='#100d1a';ctx.fillRect(0,0,W,H);const k=clamp(bossIntroClock/2,0,1);for(let y=0;y<H;y+=24){ctx.fillStyle=y%48?'#341624':'#201321';ctx.fillRect(0,y,W,5)}for(let i=0;i<14;i++){const x=(i*125+t*30)%W;ctx.fillStyle='#6f2d4333';ctx.fillRect(x,0,2,H);ctx.fillStyle='#f1768b55';ctx.fillRect(x,Math.floor((i*79+t*21)%H/4)*4,6,20)}ctx.save();ctx.translate(860,350);ctx.rotate(-.11);ctx.fillStyle='#4a2334';ctx.fillRect(-180,-210,360,420);ctx.strokeStyle='#9e5266';ctx.lineWidth=4;ctx.strokeRect(-174,-204,348,408);ctx.restore();ctx.fillStyle='#e185a2';ctx.font='bold 16px monospace';ctx.textAlign='left';ctx.fillText('ACCESS DENIED  /  唯一答案协议',100,145);ctx.fillStyle='#fff0e5';ctx.font='bold 68px monospace';ctx.fillText('坍缩守卫',100,255);ctx.fillStyle='#d9a8ba';ctx.font='bold 25px monospace';ctx.fillText('闭源型 · ARCHIVE WARDEN',104,305);ctx.font='18px monospace';ctx.fillStyle='#b58e9f';ctx.fillText('曾为保存记忆而生，最终封锁了所有不同的未来。',105,375);ctx.fillText('“未经授权的明天，全部删除。”',105,418);ctx.fillStyle='#6e3349';ctx.fillRect(105,466,450,3);ctx.fillStyle='#ed91a8';ctx.fillRect(105,466,450*k,3);drawSprite('boss',880,515-Math.sin(Math.min(1,bossIntroClock/1.4)*Math.PI)*22,345,{alpha:.3+.7*k,squash:1+Math.sin(t*4)*.025});ctx.fillStyle='#ee9cae';ctx.fillRect(838,313,24,6);ctx.fillRect(902,313,24,6);ctx.fillStyle='#eab4c3';ctx.font='14px monospace';ctx.fillText('入口锁定 · 落地激光连招 · 用精准换界制造反击',105,552);}
function drawBossDefeat(t){const e=fallenBoss,progress=clamp(bossDeathClock/2,0,1),x=e.x-camera.x,y=e.y-camera.y;ctx.save();ctx.translate(x,y);ctx.globalAlpha=1-progress;drawSprite('boss',0,70+progress*42,175*(1-progress*.2),{rotation:progress*.38,flash:Math.floor(bossDeathClock*10)%2===0});ctx.globalAlpha=1;for(let i=0;i<28;i++){const a=i*2.399,d=30+progress*(90+i*3);ctx.fillStyle=i%3?'#dd7f9c':'#a1f4e7';ctx.fillRect(Math.cos(a)*d,Math.sin(a)*d-progress*35,5-progress*3,5-progress*3)}ctx.restore();ctx.fillStyle='#09122188';ctx.fillRect(0,H-165,W,165);ctx.fillStyle='#b9f0df';ctx.textAlign='center';ctx.font='bold 30px monospace';ctx.fillText('闭源协议 · 已解除',W/2,H-105);ctx.font='16px monospace';ctx.fillStyle='#a9c6c4';ctx.fillText('封存的回响正在归还 · 归航灯重新亮起',W/2,H-65);}
function queueLandingCombo(e){e.landingComboQueued=true;const target=e.leapTarget;e.landingLaserAim=angle(target,player);bossLanes.push({x:target.x,y:target.y,a:e.landingLaserAim,length:1000,wind:Math.max(.02,e.skillTime+.025),life:.24,landing:true});if(e.fightPhase>=2)bossLanes.push({x:target.x,y:target.y,a:e.landingLaserAim+(e.skillIndex%2?.28:-.28),length:950,wind:Math.max(.03,e.skillTime+.14),life:.22,landing:true});}
function landingBullets(e){const n=e.fightPhase===1?14:e.fightPhase===2?18:22,a=angle(e,player);for(let i=0;i<n;i++){const aa=i*Math.PI*2/n+e.life*.11,delta=Math.abs(Math.atan2(Math.sin(aa-a),Math.cos(aa-a)));if(delta<.32)continue;enemyShot(e,aa,230+e.fightPhase*10,5)}bossTelemetry.landingCombos=(bossTelemetry.landingCombos||0)+1;}
function updateBoss(e,dt){const before=e.leapPart;if(e.skill==='leap'&&e.leapPart==='air'&&e.skillTime<=.56&&!e.landingComboQueued)queueLandingCombo(e);updateBossBasic(e,dt);if(e.skill==='leap'&&e.leapPart==='land'&&before==='air')landingBullets(e);}
function startBossSkill(e,id){e.airborne=false;e.airHeight=0;if(id==='leap')e.landingComboQueued=false;startBossSkillBasic(e,id);}
window.addEventListener('keydown',e=>{if(mode==='shop'&&e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeShop();return}if(mode==='bossintro'&&['KeyE','Enter','Space'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation();endBossIntro();}},{capture:true});

// Two visible timelines: terrain, projectile memory, and guided preparation.
let phaseTerrain=[],echoMemory=[],pendingCapture=[],reflectedCount=0,terrainSwitches=0,echoFlash=0,deathReady=false,deathBlend=0,lastRunBrief=null;
let tourActive=false,tourStep=0,tourWalk=false,loadoutConfirmed=false,trainingBlueDone=false,trainingRedDone=false,terrainTutorialDone=false,operatorBriefed=false;
const deathStill=document.createElement('canvas');deathStill.width=W;deathStill.height=H;
const gunRoles={rifle:'均衡推进 · 中距稳定',pulse:'快速蓄能 · 持续压制',shotgun:'近距爆发 · 慢射重击'};
const phaseRect=(x,y,w,h,p,zone)=>({x,y,w,h,phase:p,zone});
function makePhaseTerrain(){return [
 phaseRect(500,1710,160,28,0,0),phaseRect(920,1600,28,170,1,0),
 phaseRect(2400,1400,28,210,0,1),phaseRect(2400,1800,28,200,0,1),phaseRect(2650,1580,28,240,1,1),
 phaseRect(4100,650,28,250,0,3),phaseRect(4380,600,28,260,1,3),
 phaseRect(6000,400,220,28,0,4),phaseRect(6450,550,28,240,1,4),
 phaseRect(5800,1900,28,180,0,5),phaseRect(6470,2130,180,28,1,5)
 ];}
function terrainForWorld(){return inLobby?[phaseRect(680,760,110,28,0,'hub'),phaseRect(815,690,28,110,1,'hub')]:phaseTerrain;}
function overlapsRect(x,y,r,o){return x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h;}
function worldBlocked(x,y,r=14){if(worldBlockedV10(x,y,r))return true;return terrainForWorld().some(o=>o.phase===phase&&overlapsRect(x,y,r,o));}
function createWorld(){createWorldV10();phaseTerrain=makePhaseTerrain();echoMemory=[];pendingCapture=[];reflectedCount=0;terrainSwitches=0;echoFlash=0;deathReady=false;deathBlend=0;}
function settleTerrainActors(){for(const e of enemies){if(e.dead||e.airborne||!terrainForWorld().some(o=>o.phase===phase&&overlapsRect(e.x,e.y,e.r,o)))continue;let found=null;for(let r=25;r<=200&&!found;r+=20)for(let i=0;i<16;i++){const a=i*Math.PI/8,p={x:e.x+Math.cos(a)*r,y:e.y+Math.sin(a)*r};if((inLobby||inside(p,zones[roomIndex],55))&&!blocked(p.x,p.y,e.r)){found=p;break}}if(found){e.x=found.x;e.y=found.y;ring(e.x,e.y+10,35,'#bcf5ed',.25)}}worldNav=null;navTimer=0;}
function counterVolley(){if(!pendingCapture.length){counterVolleyV10();return}if(player.counterExtra>0){const targets=enemies.filter(e=>!e.dead&&e.state!=='spawn'&&!e.airborne&&dist(e,player)<850).sort((a,b)=>dist(a,player)-dist(b,player));for(let i=0;i<player.counterExtra&&targets.length;i++){const a=angle(player,targets[i%targets.length])+(i-.5)*.05;bullets.push({x:player.x+Math.cos(a)*28,y:player.y-5+Math.sin(a)*28,vx:Math.cos(a)*650,vy:Math.sin(a)*650,r:5,damage:14,life:1.3,pierce:0,hit:new Set(),red:phase,canBounce:false,bounces:0})}}}
function switchPhase(){if(mode!=='play'||player.shiftCd>0){switchPhaseV10();return}const desired=1-phase;if(terrainForWorld().some(o=>o.phase===desired&&overlapsRect(player.x,player.y,player.r+3,o))){toast('该轮廓切换后会实体化 · 先移出轮廓，再按Tab',2);return}const perfect=!inLobby&&player.perfectCd<=0&&impendingHit();pendingCapture=perfect?enemyBullets.filter(b=>b.life>0&&b.kind!=='rocket'&&dist(b,player)<player.shiftRadius).slice(0,12+(player.counterExtra||0)).map(b=>({x:b.x,y:b.y,vx:b.vx,vy:b.vy,r:b.r,kind:b.kind||'bullet',style:b.style||'dot'})):[];const before=phase;switchPhaseV10();if(phase!==before){terrainSwitches++;settleTerrainActors();if(inLobby&&terrainForWorld().some(o=>dist(player,{x:o.x+o.w/2,y:o.y+o.h/2})<240))terrainTutorialDone=true;if(pendingCapture.length){echoMemory.push({time:.3,shots:pendingCapture.map(b=>({...b})),phase});echoFlash=1.2;toast('回响刻录 '+pendingCapture.length+' 发 · 原有形状即将反向返还',2.4);}updateTour();}pendingCapture=[];}
function tickEchoMemory(dt){for(const m of echoMemory){m.time-=dt;if(m.time<=0){for(const b of m.shots){if(blocked(b.x,b.y,b.r))continue;bullets.push({...b,vx:-b.vx,vy:-b.vy,damage:player.damage*.9+12,life:1.8,pierce:0,hit:new Set(),red:m.phase,echo:true,canBounce:false,bounces:0});reflectedCount++;}sound.tone(520,.13,'triangle',.05,1000)}}echoMemory=echoMemory.filter(m=>m.time>0);echoFlash=Math.max(0,echoFlash-dt);}
function drawEchoMemory(t){for(const m of echoMemory)for(const b of m.shots){ctx.strokeStyle='#f1db9b';ctx.lineWidth=2;ctx.strokeRect(b.x-8,b.y-8,16,16);ctx.fillStyle=m.phase?'#ff9abc':'#a0f4f1';ctx.fillRect(b.x-3,b.y-3,6,6);const a=Math.atan2(-b.vy,-b.vx);ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x+Math.cos(a)*22,b.y+Math.sin(a)*22);ctx.stroke();}}
function damageEnemy(e,n,sourcePhase=phase){damageEnemyV10(e,n,sourcePhase);if(inLobby&&e.training&&n>0){if(sourcePhase===0&&e.affinity==='rift')trainingBlueDone=true;if(sourcePhase===1&&e.affinity==='shield')trainingRedDone=true;updateTour();}}
function enterLobbyV11(){if(!inLobby&&player&&elapsed>0)lastRunBrief={kills,elapsed,reflectedCount,terrainSwitches,echoSaved,cleared:clearedRooms.size};introRead=true;enterLobbyV10();$('#radioPanel').hidden=true;radioTime=0;echoMemory=[];player.x=780;player.y=735;obstacles=[{x:385,y:390,w:80,h:45},{x:590,y:350,w:120,h:45},{x:835,y:250,w:240,h:55},{x:1160,y:850,w:150,h:30}];tourWalk=false;loadoutConfirmed=false;trainingBlueDone=false;trainingRedDone=false;terrainTutorialDone=false;operatorBriefed=false;let seen=false;if(!qaMode)try{seen=localStorage.getItem('yanyue-tour-v11')==='1'}catch{}tourActive=!seen;updateTour();updateHUD();}
function startTour(){tourWalk=false;loadoutConfirmed=false;trainingBlueDone=false;trainingRedDone=false;terrainTutorialDone=false;operatorBriefed=false;tourActive=true;updateTour();}
function skipTour(){tourActive=false;$('#tourPanel').hidden=true;if(!qaMode)try{localStorage.setItem('yanyue-tour-v11','1')}catch{}}
function tourData(){return [
 {title:'先走两步，熟悉观测站',text:'WASD移动。发光地标分别通向装备、训练与出发区。',point:{x:900,y:650},done:tourWalk},
 {title:'在武器架确认出击装备',text:'靠近上方武器架按E，比较三把枪，再装备一把。Q可快速切枪。',point:{x:900,y:330},done:loadoutConfirmed},
 {title:'试射：用双界打不同的靶',text:'下方训练区：红界破蓝盾靶，蓝界压制裂隙靶。鼠标射击，Tab换界。',point:{x:415,y:800},done:trainingBlueDone&&trainingRedDone},
 {title:'让地形跟着你一起切换',text:'靠近中间青、粉轮廓，按Tab。与当前世界同色的掩体才会挡人挡弹。',point:{x:750,y:720},done:terrainTutorialDone},
 {title:'向调度员了解行动',text:'靠近调度员·零按E。任务终端只显示目标与记录，不重复播放她的对话。',point:{x:650,y:430},done:operatorBriefed},
 {title:'准备好了，沿归航灯出发',text:'右侧传送门按E。引导不限制出击；也可随时跳过。',point:{x:1420,y:640},done:false}
 ];}
function updateTour(){const active=tourActive&&inLobby&&mode==='play';$('#tourPanel').hidden=!active;if(!active)return;const list=tourData();tourStep=list.findIndex(v=>!v.done);if(tourStep<0)tourStep=5;const d=list[tourStep];$('#tourCount').textContent='上手指引 '+(tourStep+1)+' / 6';$('#tourTitle').textContent=d.title;$('#tourText').textContent=tourStep===2?d.text+' '+(trainingRedDone?'红界靶✓ ':'红界靶待试 ')+(trainingBlueDone?'蓝界靶✓':'蓝界靶待试'):d.text;$('#tourProgress').style.width=100*tourStep/5+'%';}
function briefingV11(){openDialogue([['调度员·零 / 行动建议','坍缩守卫采用闭源型封锁，坚守唯一答案。我们要把被封存的回响带回来。'],['调度员·零 / 双界战术','蓝界的青色掩体能挡弹，红界时它会虚化；粉色掩体则相反。先用地形留好退路，再换界破盾。精准换界还能把普通弹幕原样返还。']],()=>{operatorBriefed=true;updateTour()});}
function openMissionBoard(){if(!inLobby||mode!=='play')return;setMode('missionboard');$('#missionRecord').textContent=lastRunBrief?`上次行动：${lastRunBrief.kills}次清除 / ${timeText(lastRunBrief.elapsed)} / 地形切换${lastRunBrief.terrainSwitches}次 / 返还${lastRunBrief.reflectedCount}发弹幕`:'尚无行动记录。先在训练区熟悉双界，再从右侧传送门出发。';}
function openLoadout(){if(!inLobby||mode!=='play')return;setMode('loadout');paintLoadout();}
function paintLoadout(){$('#loadoutCards').replaceChildren();for(const id of ['rifle','pulse','shotgun']){const g=weapons[id],selected=selectedStarter===id,b=document.createElement('button');b.className='loadout-card'+(selected?' selected':'');b.innerHTML=`<small>${selected?'当前出击':'可选出击装备'}</small><span class="gun-pixel ${id}"><i></i></span><h3>${g.name}</h3><p>${gunRoles[id]}</p><dl><dt>蓝界 / ${g.blue}</dt><dd>${g.count}发 × ${(13*g.blueDamage).toFixed(1)}伤害</dd><dt>红界 / ${g.red}</dt><dd>1发 × ${(13*g.redDamage).toFixed(1)}伤害</dd><dt>基础间隔</dt><dd>${(.22*g.delay).toFixed(2)}秒 · 红界×1.12</dd></dl><strong>${selected?'确认这把枪':'装备这把枪'}</strong>`;b.onclick=()=>equipLoadout(id);$('#loadoutCards').append(b);}}
function equipLoadout(id){if(mode!=='loadout'||!weapons[id])return;selectedStarter=id;weaponIndex=arsenal.indexOf(id);loadoutConfirmed=true;sound.click();setMode('play');toast('出击装备已确认：'+weapons[id].name+' · 去下方靶场试射',3);updateHUD();updateTour();}
function closeHubPanel(){if(['loadout','missionboard'].includes(mode)){setMode('play');updateTour()}}
function interact(){if(inLobby&&mode==='play'){const p=[...hubPoints].sort((a,b)=>dist(a,player)-dist(b,player))[0];if(!p||dist(p,player)>115)return;if(p.id==='rack')openLoadout();else if(p.id==='terminal')openMissionBoard();else if(p.id==='brief')briefing();else if(p.id==='portal'){skipTour();beginBoarding()}return}interactV10();}
function updateRoomPrompt(){updateRoomPromptV10();if(inLobby){const p=[...hubPoints].sort((a,b)=>dist(a,player)-dist(b,player))[0];if(p&&dist(p,player)<115)$('#interactPrompt').textContent={rack:'E 武器架 · 对比形态 / 选择出击装备',terminal:'E 任务终端 · 查看目标与行动记录',brief:'E 调度员·零 · 剧情与战术建议',portal:'E 裂隙传送门 · 开始行动'}[p.id];}}
function killEnemy(e){const wasDead=e.dead;killEnemyV10(e);if(e.type==='boss'&&!wasDead&&e.dead){deathReady=false;deathBlend=0;echoMemory=[];$('#defeatPanel').hidden=false;$('#defeatContinue').hidden=true;$('#radioPanel').hidden=true;radioTime=0;}}
function continueAfterDefeat(){if(mode!=='bossdeath'||bossDeathClock<5)return;deathStill.getContext('2d').drawImage(canvas,0,0);setMode('play');finish(true);deathBlend=1;$('#endingPanel').style.opacity='0';}
function updateV11(dt){if(mode==='bossdeath'){bossDeathClock+=dt;camera.x=lerp(camera.x,fallenBoss.x-W/2,Math.min(1,dt*2.8));camera.y=lerp(camera.y,fallenBoss.y-H/2,Math.min(1,dt*2.8));if(bossDeathClock>=2.1&&!roomCleared){roomCleared=true;clearedRooms.add(roomIndex);sound.tone(400,.5,'triangle',.06,820)}deathReady=bossDeathClock>=5;$('#defeatContinue').hidden=!deathReady;return}if(['loadout','missionboard'].includes(mode))return;if(mode==='epilogue'&&deathBlend>0){deathBlend=Math.max(0,deathBlend-dt/1.05);$('#endingPanel').style.opacity=String(1-deathBlend)}updateV10(dt);if(mode==='play'){if(!inLobby)tickEchoMemory(dt);else{if(Math.hypot(player.x-780,player.y-735)>70)tourWalk=true;updateTour();}}}
function setModeV11(next){setModeV10(next);$('#loadoutPanel').hidden=next!=='loadout';$('#missionPanel').hidden=next!=='missionboard';$('#defeatPanel').hidden=next!=='bossdeath';if(next!=='bossdeath')$('#defeatContinue').hidden=true;if(next!=='epilogue')$('#endingPanel').style.opacity='1';if(next!=='play')$('#tourPanel').hidden=true;}
