function renderV11(t){if(mode==='title'||mode==='guide'){drawTitleObservatory(t);return}if(mode==='bossdeath'){drawDefeatSequence(t);return}if(inLobby){ctx.fillStyle='#08131d';ctx.fillRect(0,0,W,H);camera.x=80-(W-1650*.72)/2/.72;camera.y=150-(H-900*.72)/2/.72;ctx.save();ctx.scale(.72,.72);ctx.translate(-camera.x,-camera.y);drawHub(t);drawPhaseTerrain(t);drawTourPath(t);ctx.restore();return}renderV10(t);if(mode==='play'){ctx.save();ctx.translate(-camera.x,-camera.y);drawEchoMemory(t);ctx.restore();}if(mode==='epilogue'&&deathBlend>0){ctx.globalAlpha=deathBlend;ctx.drawImage(deathStill,0,0);ctx.globalAlpha=1;}}
